def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    total_nodes = len(distance_matrix)
    unvisited_count = len(unvisited_nodes)
    weight_factor = unvisited_count / total_nodes

    def heuristic_score(node):
        connectivity = sum(1 for neighbor in unvisited_nodes if distance_matrix[node][neighbor] < float('inf'))
        variance_reduction = sum(distance_matrix[node][neighbor] for neighbor in unvisited_nodes) / unvisited_count if unvisited_count > 0 else 0
        return (distance_matrix[current_node][node] * (1 + weight_factor)) - (0.3 * distance_matrix[node][destination_node]) + (0.3 * connectivity) - (0.1 * variance_reduction)

    next_node = min(unvisited_nodes, key=lambda node: heuristic_score(node))
    return next_node
